// Error types raised by the Python-emulating layers plus the PyInstaller-style
// traceback renderer used for uncaught exceptions.

// Raised by pyInt() -- the analogue of Python's ValueError.
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyValueError';
  }
}

// Raised by encodeAscii().  `start` and `end` delimit the offending run of
// code points (end is exclusive, exactly like CPython's UnicodeEncodeError).
export class PyUnicodeEncodeError extends Error {
  constructor(encoding, codePoint, start, end) {
    super('unicode encode error');
    this.name = 'PyUnicodeEncodeError';
    this.encoding = encoding;
    this.codePoint = codePoint;
    this.start = start;
    this.end = end;
  }

  // CPython renders the offending character with a \x / \u / \U escape whose
  // hex digits are lowercase and zero padded.
  escapedChar() {
    const cp = this.codePoint;
    const hex = cp.toString(16);
    if (cp <= 0xff) return '\\x' + hex.padStart(2, '0');
    if (cp <= 0xffff) return '\\u' + hex.padStart(4, '0');
    return '\\U' + hex.padStart(8, '0');
  }

  // str(exc) for a UnicodeEncodeError.
  toPythonString() {
    if (this.end - this.start === 1) {
      return (
        "'" + this.encoding + "' codec can't encode character '" +
        this.escapedChar() + "' in position " + this.start +
        ': ordinal not in range(128)'
      );
    }
    return (
      "'" + this.encoding + "' codec can't encode characters in position " +
      this.start + '-' + (this.end - 1) + ': ordinal not in range(128)'
    );
  }
}

// Signals that the program should terminate with the given status.  Any text
// already produced is written by the caller.
export class SystemExit extends Error {
  constructor(status) {
    super('system exit ' + status);
    this.name = 'SystemExit';
    this.status = status;
  }
}

const SCRIPT_FILE = 'test12.py';
const SCRIPT_NAME = 'test12';

// The frozen (PyInstaller) build has no source available, so the traceback
// shows the File/line header with no source line and no caret underline.
export function renderTraceback(lineNumber, exceptionName, exceptionMessage, pid) {
  return (
    'Traceback (most recent call last):\n' +
    '  File "' + SCRIPT_FILE + '", line ' + lineNumber + ', in <module>\n' +
    exceptionName + ': ' + exceptionMessage + '\n' +
    '[PYI-' + pid + ':ERROR] Failed to execute script ' +
    "'" + SCRIPT_NAME + "' due to unhandled exception!\n"
  );
}
